  base_receipt_id: string | null;
  quest_id: string;
  run_id: string;
  path: string;
  execution_mode: "live" | "mock";
  change: "created" | "revised";
  created_at: string;
  sha256: string;
  base_sha256: string | null;
  added: number;
  removed: number;
  text: string;
  truncated: boolean;
  origin: { original_request_message_id: string | null; goal_update_message_id: string | null } | null;
