.settings-group > .settings-row:last-child, .settings-section > .settings-row:last-child { border-bottom: 0; }
.settings-row-text { min-width: 0; flex: 1; }
.settings-row-label { font-size: 13px; line-height: 18.5714px; font-weight: 500; }
.settings-row-desc { margin-top: 2px; color: var(--color-text-secondary); font-size: 12px; line-height: 16px; }
.settings-row-control { display: inline-flex; align-items: center; gap: 8px; flex: none; min-width: min(160px,40%); max-width: 52%; font-size: 13px; line-height: 18.5714px; overflow-wrap: anywhere; }
.settings-row-value { justify-content: flex-end; color: var(--color-text-secondary); text-align: right; }
.settings-content .inspector-header { position: absolute; top: 20px; right: 20px; height: 30px; min-height: 0; padding: 0; border: 0; }
.settings-content .inspector-header > div { display: none; }
.settings-content .inspector-body { padding: 0; overflow: visible; }
.settings-content .field-label { display: grid; grid-template-columns: minmax(0,1fr) minmax(160px,48%); align-items: center; gap: 24px; margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); color: var(--color-text); font-size: 13px; line-height: 18.5714px; }
.settings-content .field-label input, .settings-content .field-label select, .settings-content .field-label textarea { min-height: 28px; padding: 4px 12px; background: var(--app-color-background-surface); font-size: 13px; line-height: 18px; }
.settings-content .check-label { margin: 0; padding: 12px 16px; border-bottom: 1px solid var(--color-border-subtle); font-size: 13px; line-height: 18.5714px; }
.settings-content .check-label input { order: 1; margin-left: auto; }
.settings-content .config-form { padding: 0 0 16px; border: 1px solid var(--color-border-strong); border-radius: 16px; overflow: hidden; }
