  background: var(--app-color-background-surface); font-synthesis: none; text-rendering: optimizeLegibility;
}
[data-theme="dark"] {
  --color-text-secondary: rgba(252,252,252,.71); --color-border-strong: rgba(252,252,252,.14);
  --color-background-nav-active: rgba(252,252,252,.078); --color-background-control-subtle: rgba(252,252,252,.04);
  --color-background-command: rgba(252,252,252,.055); --color-sidebar-surface: rgba(17,17,17,.65);
  --color-shell-background: var(--app-color-background-surface-under);
  --color-git-added: #00a240; --color-git-modified: #0285ff; --color-git-removed: #e02e2a;
  --color-filetree-selected-bg: rgba(252,252,252,.052);
  --color-syntax-keyword: #db9ee5; --color-syntax-string: #9acaa7; --color-syntax-number: #d9bd85;
  --color-status-error: #ff9c94; --color-status-warning: #e0b471;
  --color-background-warning: #2a241b; --color-border-warning: #66523c; --color-scrollbar: rgba(252,252,252,.22);
}
* { box-sizing: border-box; scrollbar-width: thin; scrollbar-color: var(--color-scrollbar) transparent; }
html, body, #root { height: 100%; margin: 0; overflow: hidden; }
/* Native html keeps the browser's 16px rem base; the UI uses a separate 14px size. */
body { font-size: 14px; }
button, input, textarea, select { font: inherit; color: inherit; }
button, summary { cursor: pointer; }
button:disabled { cursor: not-allowed; opacity: .4; }
.preview-empty > svg { width: 28px; height: 28px; margin-bottom: 10px; }
