.file-tree-divider::before { content: ""; position: absolute; inset-block: 0; left: 7px; width: 1px; background: var(--color-border-strong); opacity: 0; transition: opacity .15s var(--ease-out); }
.file-tree-divider:hover::before, .file-tree-divider:focus-visible::before { opacity: 1; }
.file-tree-search { display: flex; align-items: center; gap: 6px; min-width: 0; min-height: 30px; margin: 0 8px 4px; padding: 0 10px; border: .8px solid var(--color-border); border-radius: 999px; color: var(--muted); }
.file-tree-search > svg { flex: none; }
