.file-tree-scopes button[aria-pressed="true"], .file-tree-scopes button:hover { color: var(--color-text); background: var(--color-background-secondary-ghost-hover); }
.file-tree-scopes > span { display: flex; align-items: center; padding-inline: 4px; color: var(--muted); }
.file-tree-scopes .file-tree-all-changes { display: flex; align-items: center; gap: 5px; flex: 1; padding-inline: 3px; color: var(--color-text); text-align: left; font-size: 14px; font-weight: 400; }
.file-tree-section { min-width: 0; }
.file-tree-section + .file-tree-section { margin-top: 4px; border-top: .8px solid var(--color-border-subtle); }
.file-tree-section-heading { display: flex; align-items: center; gap: 5px; width: 100%; min-width: 0; height: 30px; min-height: 30px; padding: 4px 3px; border: 0; border-radius: 6px; background: transparent; color: var(--color-text); text-align: left; font-size: 13px; font-weight: 400; line-height: 21px; }
.file-tree-section-heading > span:nth-child(2) { flex: 1; min-width: 0; }
.file-tree-section-heading:hover { background: var(--color-background-secondary-ghost-hover); }
